/** Pure roster, follow-mode and turn-summary logic for the board. Plain
 *  JavaScript on purpose: the gate tests execute this exact file, and the
 *  React components import it, so the behaviour under test is the behaviour
 *  that ships. Everything here is a calculation — no DOM, no store — except
 *  the static agent marks, which are data. */

export function clampPaneWidth(v, min, max) {
  v = Number(v);
  if (!isFinite(v)) return min;
  return Math.max(min, Math.min(max, Math.round(v)));
}

export function newestHunk(hunks) {
  let best = null;
  (hunks || []).forEach((h) => {
    if (h && typeof h.start === "number" && (!best || h.start > best.start)) best = h;
  });
  return best;
}

export function followAllows(mode, actor, myActor) {
  if (mode === "off") return false;
  if (mode === "all") return true;
  return Boolean(myActor && actor === myActor);
}

export function lastToolFor(events, repoName, relPath) {
  const evts = events || [];
  for (let i = evts.length - 1; i >= 0; i--) {
    const ev = evts[i];
    if (ev && ev.kind === "tool" && ev.repo === repoName && ev.target === relPath) return ev;
  }
  return null;
}

/**
 * `lastToolFor`, but for every touched path at once — the map the file-tree
 * sprite needs. Built once per render (the tree can run to thousands of
 * rows), so this walks `events` a single time rather than having each row
 * call `lastToolFor` for its own path.
 *
 * Reuses `followAllows` rather than re-deriving "off shows nothing / mine
 * shows only me" here, so the tree's follow-mode gate cannot drift from the
 * one the editor rider already applies.
 *
 * ⚠️ LATEST WINS BY TIMESTAMP, not by array position. `events` is normally
 * append-ordered, but comparing `ev.ts` directly means a caller that hands in
 * an unordered slice still gets the right answer instead of a silently wrong
 * one.
 */
export function spritesByPath(events, { repoName, followMode, myActor, now, idleAfterMs }) {
  const out = {};
  (events || []).forEach((ev) => {
    if (!ev || ev.kind !== "tool" || !ev.target) return;
    if (repoName && ev.repo !== repoName) return;
    if (!followAllows(followMode, ev.actor, myActor)) return;
    if (now - ev.ts > idleAfterMs) return;
    const prev = out[ev.target];
    if (!prev || ev.ts >= prev.ts) out[ev.target] = { actor: ev.actor, tool: ev.tool, ts: ev.ts };
  });
  return out;
}

/** Everything of an actor's since their most recent prompt. */
export function turnTrace(events, actor) {
  const mine = (events || []).filter((e) => e && e.actor === actor);
  let startIdx = 0;
  for (let i = mine.length - 1; i >= 0; i--) {
    if (mine[i].kind === "prompt") {
      startIdx = i;
      break;
    }
  }
  const turn = mine.slice(startIdx);
  return {
    prompt: turn[0] && turn[0].kind === "prompt" ? turn[0] : null,
    tools: turn.filter((e) => e.kind === "tool"),
    ended: turn.some((e) => e.kind === "turn_end"),
  };
}

/** The one-line mission and the current command, as the roster shows them. */
export function turnSummary(entry, events) {
  const t = turnTrace(events, entry && entry.actor);
  const mission = t.prompt && t.prompt.detail ? String(t.prompt.detail).slice(0, 80) : "";
  const e = t.tools[t.tools.length - 1];
  const current = e
    ? (e.tool || "tool") + (e.target || e.detail ? "  " + (e.target || e.detail) : "")
    : t.ended ? "turn finished" : "";
  return { mission, current };
}

export function verbFor(e) {
  if (!e) return "working";
  if (e.kind === "prompt") return "asked";
  if (e.kind === "turn_end") return "finished";
  return e.tool || "working";
}

/** The folder a teammate is working in — the thing you want at a glance. */
export function folderOf(e) {
  if (!e || !e.target) return e && e.detail ? String(e.detail).slice(0, 40) : "";
  const parts = String(e.target).split("/");
  parts.pop();
  return parts.length ? parts.join("/") + "/" : "./";
}

export function ago(ms) {
  const s = Math.max(0, Math.round(ms / 1000));
  if (s < 60) return s + "s";
  const m = Math.round(s / 60);
  if (m < 60) return m + "m";
  return Math.round(m / 60) + "h";
}

export function agoText(now, ts) {
  return ago(now - ts) + " ago";
}

/** The active collaborators whose last event is in a repo — one dot each. */
export function liveActorsOf(roster, repoName) {
  if (!repoName) return [];
  return (roster || []).filter((r) => r && r.lastEvent && r.lastEvent.repo === repoName);
}

